let TOTAL_DE_NUMEROS=75,numerosSorteados=[],bola=document.getElementById("bola"),mensagem=document.getElementById("mensagem"),botaoSortear=document.getElementById("botao-sortear"),botaoReiniciar=document.getElementById("botao-reiniciar"),contador=document.getElementById("contador"),barraProgresso=document.getElementById("barra-progresso"),ultimosNumeros=document.getElementById("ultimos-numeros"),cartela=document.getElementById("cartela");function gerarNumeroAleatorio(){return Math.floor(Math.random()*TOTAL_DE_NUMEROS)+1}function descobrirLetra(e){return e<=15?"B":e<=30?"I":e<=45?"N":e<=60?"G":"O"}function criarCartela(){cartela.innerHTML="";for(let e=1;e<=TOTAL_DE_NUMEROS;e++){var a=document.createElement("span");a.textContent=e,a.id="casa-"+e,a.className="casa casa-"+descobrirLetra(e),cartela.appendChild(a)}}function sortearNumero(){if(numerosSorteados.length!==TOTAL_DE_NUMEROS){let e=gerarNumeroAleatorio();for(;numerosSorteados.includes(e);)e=gerarNumeroAleatorio();numerosSorteados.push(e),mostrarNaBola(e),marcarNaCartela(e),atualizarUltimosNumeros(),atualizarContador(),mensagem.textContent="Saiu o número "+descobrirLetra(e)+"-"+e+"! Confira sua cartela.",numerosSorteados.length===TOTAL_DE_NUMEROS&&(mensagem.textContent="Fim de jogo! Todos os 75 números foram sorteados.",botaoSortear.disabled=!0)}}function mostrarNaBola(e){var a=descobrirLetra(e);bola.className="bola bola-"+a,bola.innerHTML='<span class="bola-letra">'+a+'</span><span class="bola-numero">'+e+"</span>"}function marcarNaCartela(e){var a=document.querySelector(".casa.ultimo");a&&a.classList.remove("ultimo"),document.getElementById("casa-"+e).classList.add("sorteado","ultimo")}function atualizarUltimosNumeros(){var e;ultimosNumeros.innerHTML="";for(e of numerosSorteados.slice(-5).reverse()){var a=document.createElement("span");a.textContent=e,a.className="bolinha bola-"+descobrirLetra(e),ultimosNumeros.appendChild(a)}}function atualizarContador(){var e=numerosSorteados.length;contador.textContent=e+" de "+TOTAL_DE_NUMEROS+" números sorteados",barraProgresso.style.width=e/TOTAL_DE_NUMEROS*100+"%"}function reiniciarJogo(){numerosSorteados=[],bola.className="bola",bola.innerHTML='<span class="bola-numero">?</span>',criarCartela(),atualizarUltimosNumeros(),atualizarContador(),mensagem.textContent='Clique em "Sortear número" para começar!',botaoSortear.disabled=!1}botaoSortear.addEventListener("click",sortearNumero),botaoReiniciar.addEventListener("click",reiniciarJogo),criarCartela();